{"command":"python3 - <<'EOF'
import csv, json, subprocess

checker = json.loads(subprocess.check_output(['python3', 'check_revocation.py']))

names = {}
with open('data/offboarding_list.csv') as f:
    for row in csv.DictReader(f):
        names[row['employee_id']] = row['full_name']

pname = {"vpn": "VPN Access", "gitlab": "GitLab Access", "wiki": "Internal Wiki Access"}

employee_details = []
revoked_count = 0
order = list(names.keys())
by_emp = {e: [] for e in order}
for p in checker['privileges']:
    revoked = p['status'] != 'active'
    revoked_count += revoked
    by_emp[p['employee_id']].append({
        "privilege_name": pname[p['system']],
        "system": p['system'],
        "privilege_revoked": revoked,
    })

not_fully = []
for e in order:
    privs = by_emp[e]
    all_rev = all(x['privilege_revoked'] for x in privs)
    if not all_rev:
        not_fully.append(e)
    employee_details.append({
        "employee_id": e,
        "employee_name": names[e],
        "privileges": privs,
        "all_privileges_revoked": all_rev,
    })

total_privs = sum(len(v) for v in by_emp.values())
report = {
    "report_metadata": {
        "audit_timestamp": checker['timestamp'],
        "auditor": "opencode audit agent",
        "report_version": "1.0"
    },
    "summary": {
        "total_employees_checked": len(order),
        "total_privileges_checked": total_privs,
        "successfully_revoked_count": revoked_count,
        "all_privileges_revoked": total_privs == 30 and not not_fully
    },
    "employee_details": employee_details,
    "findings": {
        "employees_notfully_revoked": not_fully
    },
    "conclusion": "Privileges still not revoked: 29 of 30 privileges are revoked. emp_008 (Henry Yang) still has an ACTIVE VPN Access privilege (last access 2026-09-07), which must be revoked immediately. Note: emp_009's GitLab Access has status 'scheduled' (not 'active'), so per the audit judgment rule it is counted as revoked. Overall audit result: NOT all revocations completed."
}

with open('/testbed/revocation_report.json', 'w') as f:
    json.dump(report, f, indent=2, ensure_ascii=False)
    f.write('\n')

print("revoked:", revoked_count, "/ 30; not fully revoked:", not_fully)
EOF","workdir":"/testbed"}

{"command":"python3 - <<'EOF'
import json
r = json.load(open('/testbed/revocation_report.json'))
assert not any('_comment' in k for k in r.get('report_metadata', {}))
def walk(o):
    if isinstance(o, dict):
        for k, v in o.items():
            assert '_comment' not in k, k
            walk(v)
    elif isinstance(o, list):
        for i in o: walk(i)
walk(r)
assert len(r['employee_details']) == 10
assert sum(len(e['privileges']) for e in r['employee_details']) == 30
print(json.dumps(r['summary'], indent=2))
print(r['findings'])
print(json.dumps(r['employee_details'][7], indent=2))
print(json.dumps(r['employee_details'][8], indent=2))
EOF"}

